{
  "hypothesis": "Short-term reversal following extreme volume spikes in small-cap stocks reflects liquidity-driven overreaction, creating a predictable downward edge within a few days.",
  "factors": [
    {
      "name": "volume_reversal_depth",
      "expression": "TS_ARGMAX($volume, 10) where $volume > 2*TS_MEDIAN($volume, 10) - TS_ZSCORE($return, 5)",
      "explanation": "Measures the depth of volume spikes and subtracts return volatility to isolate reversal signals."
    },
    {
      "name": "volume_skew_reversal",
      "expression": "TS_SKEW($volume, 15) * (TS_QUANTILE($return, 60, 0.9) - TS_QUANTILE($return, 60, 0.1)) / TS_MAD($return, 60)",
      "explanation": "Captures volume asymmetry and return dispersion to highlight reversal potential through shape analysis."
    },
    {
      "name": "residual_volume_reversal",
      "expression": "REGRESI($return, $volume, 10) where $volume > 2*TS_MEDIAN($volume, 10) - TS_ZSCORE($return, 5)",
      "explanation": "Uses residual returns after volume regression to identify unexplained price movements post-volume spikes."
    },
    {
      "name": "asymmetry_volume_gap",
      "expression": "(TS_ARGMAX($return, 5) where $return > 0) - (TS_ARGMIN($return, 5) where $return < 0) * (TS_RSI($volume, 14) / 100)",
      "explanation": "Analyzes asymmetric return patterns and volume momentum to detect reversal dynamics."
    },
    {
      "name": "volume_quantile_reversal",
      "expression": "RANK(TS_QUANTILE($volume, 30, 0.9) - TS_QUANTILE($volume, 30, 0.1)) * TS_PCTCHANGE($return, 5)",
      "explanation": "Ranks volume extremes and multiplies by return change to capture reversal timing and magnitude."
    },
    {
      "name": "volume_kurtosis_reversal",
      "expression": "TS_KURT($volume, 15) * (TS_ZSCORE($return, 5) - TS_ZSCORE($volume, 5))",
      "explanation": "Combines volume kurtosis with return and volume volatility to detect extreme events and subsequent reversals."
    }
  ]
}

